// Unit tests for extension/sourcemap.js: the VLQ decoder, the mapping lookup and the fetch policy,
// against a real esbuild map (test/site/sourcemap, regenerated by test/fixtures/sourcemap/build.sh).
// Run: node --test ui-sourcemap.test.mjs. Loads the file the way the worker does: a classic script.
import { test } from "node:test";
import assert from "node:assert/strict";
import fs from "node:fs";
import path from "node:path";
import vm from "node:vm";
import { createRequire } from "node:module";
import { fileURLToPath } from "node:url";

const here = path.dirname(fileURLToPath(import.meta.url));
const sandbox = { URL, AbortController, TextDecoder, Blob, setTimeout, clearTimeout, atob, Uint8Array, Int8Array, Promise, Error, JSON, Date, Map, Set };
vm.runInNewContext(fs.readFileSync(path.resolve(here, "../extension/sourcemap.js"), "utf8"), sandbox);
const SM = sandbox.pinpointSourceMap;
const BUNDLE = fs.readFileSync(path.join(here, "site/sourcemap/app.min.js"), "utf8");
const MAP = fs.readFileSync(path.join(here, "site/sourcemap/app.min.js.map"), "utf8");
const plain = (v) => JSON.parse(JSON.stringify(v)); // out of the vm's realm, for deepEqual

test("VLQ: single values, signs, continuation bits, line breaks", () => {
  // A=0 C=+1 D=-1; g/h set the continuation bit, so gB=+16 hB=-16 2H=+123 +/D=+2047 //D=-2047
  assert.deepEqual(plain(SM.decodeMappings("AAAA")), [[[0, 0, 0, 0]]]);
  assert.deepEqual(plain(SM.decodeMappings("CACA,DADA")), [[[0, 0, 0, 0], [1, 0, 1, 0]]]);
  assert.deepEqual(plain(SM.decodeMappings("gBAAA")), [[[16, 0, 0, 0]]]);
  assert.deepEqual(plain(SM.decodeMappings("hBAAA")), [[[-16, 0, 0, 0]]]);
  assert.deepEqual(plain(SM.decodeMappings("2HAAA")), [[[123, 0, 0, 0]]]);
  assert.deepEqual(plain(SM.decodeMappings("+/D")), [[[2047]]]);
  assert.deepEqual(plain(SM.decodeMappings("//D")), [[[-2047]]]);
  // genCol resets per line; source, line, column and name accumulate across lines
  assert.deepEqual(plain(SM.decodeMappings("ECAEC;;EAAE")), [[[2, 1, 0, 2, 1]], [], [[2, 1, 0, 4]]]);
  assert.throws(() => SM.decodeMappings("AA"), /bad segment/);
  assert.throws(() => SM.decodeMappings("A!AA"), /bad base64/);
});

test("decoder agrees with source-map-js on every segment of a real esbuild map", (t) => {
  let SourceMapConsumer;
  try { ({ SourceMapConsumer } = createRequire(import.meta.url)("source-map-js")); } catch { return t.skip("source-map-js not installed"); }
  const theirs = [];
  new SourceMapConsumer(JSON.parse(MAP)).eachMapping((m) => theirs.push([m.generatedLine - 1, m.generatedColumn, m.originalLine - 1, m.originalColumn, m.name || null]));
  const map = JSON.parse(MAP), mine = [];
  SM.decodeMappings(map.mappings).forEach((segs, line) => segs.forEach((s) => mine.push([line, s[0], s[2], s[3], s.length === 5 ? map.names[s[4]] : null])));
  assert.ok(mine.length > 50);
  assert.deepEqual(mine, theirs);
});

test("a minified component's position maps back to its original file, line and name", () => {
  const map = JSON.parse(MAP);
  // Column 8: esbuild maps `function` itself, after the original's `export `.
  // What inspector.js sends: the head of the function's own source text.
  const fn = BUNDLE.match(/function c\(\{amount[^]{0,100}/)[0];
  const at = SM.locate(BUNDLE, fn.slice(0, 120));
  assert.deepEqual(plain(at), { line: 0, column: BUNDLE.indexOf("function c(") });
  assert.deepEqual(plain(SM.originalPosition(map, at.line, at.column)), { file: "src/components/PriceTag.js", line: 9, column: 8, name: "PriceTag" });
  const badge = SM.locate(BUNDLE, "function a({text:n}){let t=document");
  assert.deepEqual(plain(SM.originalPosition(map, badge.line, badge.column)), { file: "src/components/PriceTag.js", line: 2, column: 8, name: "Badge" });
  // Before the first segment of a line: the first one within the function's head (120 columns)
  // stands in; further than that, and past the last line, nothing.
  assert.equal(SM.originalPosition({ ...map, _lines: undefined, mappings: "EAAA" }, 0, 1)?.column, 1);
  assert.equal(SM.originalPosition({ ...map, _lines: undefined, mappings: "wMAAA" }, 0, 1), null);
  assert.equal(SM.originalPosition(map, 5, 0), null);
});

// The two real Vite production builds in test/site/real (test/fixtures/real/build.sh).
const real = (app) => ({ text: fs.readFileSync(path.join(here, `site/real/${app}/app.js`), "utf8"), map: JSON.parse(fs.readFileSync(path.join(here, `site/real/${app}/app.js.map`), "utf8")) });

test("Vue production: <script setup>'s generated setup() has no segment of its own; the first one inside it is used", () => {
  const { text, map } = real("vue");
  const start = text.indexOf("setup(", text.indexOf('__name:"PriceCard"'));
  const at = SM.locate(text, text.slice(start, start + 120));   // what inspector.js sends: setup's own text
  const segs = SM.decodeMappings(map.mappings)[at.line];
  const before = segs.findLast((s) => s[0] <= at.column);
  assert.ok(before[0] < at.column && !/PriceCard\.vue$/.test(map.sources[before[1]]), "the segment at or before setup( belongs to another module");
  const r = plain(SM.originalPosition(map, at.line, at.column));
  assert.equal(r.file, "src/components/PriceCard.vue");
});

test("an arrow-function component's name comes from the `const` binding just before the function", () => {
  const { text, map } = real("react");
  const start = text.search(/\(\{value:\w+\}\)=>/);
  const at = SM.locate(text, text.slice(start, start + 120));
  const r = plain(SM.originalPosition(map, at.line, at.column));
  assert.equal(r.file, "src/components/Price.jsx");
  assert.equal(r.name, "Price");
  // …and a function declaration still takes the name after `function`, never the one before it.
  const card = text.search(/function \w+\(\{title:/);
  const c = SM.locate(text, text.slice(card, card + 120));
  assert.deepEqual([SM.originalPosition(map, c.line, c.column).file, SM.originalPosition(map, c.line, c.column).name], ["src/components/ProductCard.jsx", "ProductCard"]);
});

test("locate: 0-based line and column; absent or ambiguous snippets find nothing", () => {
  assert.deepEqual(plain(SM.locate("a\nbc\n  function x(){}", "function x(){}")), { line: 2, column: 2 });
  assert.deepEqual(plain(SM.locate("function x(){}", "function x(){}")), { line: 0, column: 0 });
  assert.equal(SM.locate("abc", "zzz"), null);
  assert.equal(SM.locate("f(){} f(){}", "f(){}"), null);
});

test("sources are cleaned into project-relative paths", () => {
  assert.equal(SM.cleanSource("webpack://my-app/./src/App.jsx"), "src/App.jsx");
  assert.equal(SM.cleanSource("webpack:///src/components/Nav.tsx?abc"), "src/components/Nav.tsx");
  assert.equal(SM.cleanSource("/@fs/Users/me/proj/src/main.ts"), "src/main.ts");
  assert.equal(SM.cleanSource("../../src/pages/Home.vue"), "src/pages/Home.vue");
  assert.equal(SM.cleanSource("Card.tsx", "/project/app/ui"), "app/ui/Card.tsx");
  assert.equal(SM.cleanSource("file:///home/me/x/lib/util.js"), "lib/util.js");
});

test("indexed maps: the section covering the position is used; url sections are skipped", () => {
  const inner = JSON.parse(MAP);
  const indexed = { version: 3, sections: [
    { offset: { line: 0, column: 0 }, map: { version: 3, sources: ["src/other.js"], names: [], mappings: "AAAA" } },
    { offset: { line: 3, column: 10 }, map: inner },
    { offset: { line: 9, column: 0 }, url: "elsewhere.map" },
  ] };
  const col = BUNDLE.indexOf("function c(");
  assert.equal(SM.originalPosition(indexed, 3, 10 + col).file, "src/components/PriceTag.js");
  assert.equal(SM.originalPosition(indexed, 3, 10 + col).line, 9);
  assert.equal(SM.originalPosition(indexed, 1, 0), null); // section 1 has no line 1
  assert.equal(SM.originalPosition(indexed, 0, 3).file, "src/other.js");
  assert.equal(SM.originalPosition(indexed, 9, 0), null);
});

test("sourceMappingURL: the last comment wins; none means null", () => {
  assert.equal(SM.mapComment("x\n//# sourceMappingURL=a.map\n//# sourceMappingURL=b.map\n"), "b.map");
  assert.equal(SM.mapComment("x /*# sourceMappingURL=c.css.map */"), "c.css.map");
  assert.equal(SM.mapComment("var s = 1;"), null);
});

test("fetch policy: same origin, or loopback from a loopback page; never a third party", () => {
  assert.equal(SM.allowed("http://localhost:3000/a.js", "http://localhost:3000/"), true);
  assert.equal(SM.allowed("http://127.0.0.1:5173/a.js", "http://localhost:3000/"), true);
  assert.equal(SM.allowed("https://cdn.example.com/a.js", "http://localhost:3000/"), false);
  assert.equal(SM.allowed("http://myapp.test/a.js", "http://myapp.test/x"), true);
  assert.equal(SM.allowed("http://localhost:3000/a.js", "http://myapp.test/"), false);
  assert.equal(SM.allowed("data:text/javascript,1", "http://localhost/"), false);
  assert.equal(SM.allowed("file:///a.js", "file:///index.html"), false);
});

const PAGE = "http://localhost:4000/";
const files = (extra = {}) => ({ "http://localhost:4000/app.min.js": BUNDLE, "http://localhost:4000/app.min.js.map": MAP, ...extra });
const getter = (table, seen) => async (url) => { seen.push(url); if (!(url in table)) throw new Error("404"); return { text: table[url], header: null }; };
const SNIP = BUNDLE.slice(BUNDLE.indexOf("function c("), BUNDLE.indexOf("function c(") + 120);

test("resolve: finds the script, follows its map, caches per URL", async () => {
  const seen = [];
  const get = getter(files(), seen);
  const scripts = ["http://localhost:4000/app.min.js", "https://cdn.example.com/lib.js"];
  const r = await SM.resolve({ snippet: SNIP, scripts }, PAGE, { get });
  assert.deepEqual(plain(r), { file: "src/components/PriceTag.js", line: 9, column: 8, name: "PriceTag" });
  assert.deepEqual(seen, ["http://localhost:4000/app.min.js", "http://localhost:4000/app.min.js.map"], "the third-party script is never fetched");
  await SM.resolve({ snippet: SNIP, scripts }, PAGE, { get });
  assert.equal(seen.length, 2, "both the script and its map come from the cache the second time");
});

test("resolve: a data: URL map, a cross-origin map, a missing map, a timeout", async () => {
  const b64 = Buffer.from(MAP).toString("base64");
  const seen = [];
  const inline = BUNDLE.replace(/sourceMappingURL=.*/, `sourceMappingURL=data:application/json;charset=utf-8;base64,${b64}`);
  const r = await SM.resolve({ snippet: SNIP, scripts: ["http://localhost:4000/inline.js"] }, PAGE, { get: getter({ "http://localhost:4000/inline.js": inline }, seen) });
  assert.equal(r.file, "src/components/PriceTag.js");
  const cross = BUNDLE.replace(/sourceMappingURL=.*/, "sourceMappingURL=https://maps.example.com/app.min.js.map");
  assert.equal(await SM.resolve({ snippet: SNIP, scripts: ["http://localhost:4000/cross.js"] }, PAGE, { get: getter({ "http://localhost:4000/cross.js": cross }, seen) }), null);
  const none = BUNDLE.replace(/\/\/# sourceMappingURL=.*/, "");
  assert.equal(await SM.resolve({ snippet: SNIP, scripts: ["http://localhost:4000/none.js"] }, PAGE, { get: getter({ "http://localhost:4000/none.js": none }, seen) }), null);
  assert.ok(!seen.some((u) => /example\.com/.test(u)));
  const t0 = Date.now();
  assert.equal(await SM.resolve({ snippet: SNIP, scripts: ["http://localhost:4000/slow.js"] }, PAGE, { timeout: 100, get: () => new Promise(() => {}) }), null);
  assert.ok(Date.now() - t0 < 1000);
  assert.equal(await SM.resolve({ snippet: "short", scripts: [] }, PAGE), null);
});
